CREATE TABLE IF NOT EXISTS drawing_legend_geometry_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,approved_structure_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,engine_version TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,created_by TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(approved_structure_version_id) REFERENCES drawing_structure_approved_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_legend_geometry_version_idx ON drawing_legend_geometry_versions(document_id,version_number);
CREATE INDEX IF NOT EXISTS drawing_legend_geometry_current_idx ON drawing_legend_geometry_versions(document_id,superseded_at);
CREATE TABLE IF NOT EXISTS drawing_legend_geometry_candidates (id TEXT PRIMARY KEY,geometry_version_id TEXT NOT NULL,approved_row_id TEXT NOT NULL,source_page INTEGER NOT NULL,source_row TEXT NOT NULL,symbol_cell_id TEXT,symbol_cell_bbox TEXT,geometry TEXT NOT NULL,geometry_signature TEXT,detection_confidence INTEGER NOT NULL,detection_method TEXT NOT NULL,alignment_status TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',original_geometry TEXT NOT NULL,reviewed_by TEXT,reviewed_at TEXT,review_reason TEXT,reassigned_row_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(geometry_version_id) REFERENCES drawing_legend_geometry_versions(id),FOREIGN KEY(approved_row_id) REFERENCES drawing_structure_approved_rows(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_legend_geometry_candidate_idx ON drawing_legend_geometry_candidates(geometry_version_id,approved_row_id,id);
CREATE INDEX IF NOT EXISTS drawing_legend_geometry_candidate_status_idx ON drawing_legend_geometry_candidates(geometry_version_id,review_status);
CREATE TABLE IF NOT EXISTS drawing_legend_geometry_review_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,geometry_version_id TEXT NOT NULL,candidate_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT NOT NULL,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(candidate_id) REFERENCES drawing_legend_geometry_candidates(id));
CREATE INDEX IF NOT EXISTS drawing_legend_geometry_review_event_idx ON drawing_legend_geometry_review_events(candidate_id,created_at);
CREATE TABLE IF NOT EXISTS drawing_legend_geometry_approved_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,source_geometry_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,status TEXT NOT NULL,approved_link_count INTEGER NOT NULL,missing_row_count INTEGER NOT NULL,created_by TEXT NOT NULL,reason TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_geometry_version_id) REFERENCES drawing_legend_geometry_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_legend_geometry_approved_version_idx ON drawing_legend_geometry_approved_versions(document_id,version_number);
CREATE TABLE IF NOT EXISTS drawing_legend_geometry_approved_links (id TEXT PRIMARY KEY,approved_geometry_version_id TEXT NOT NULL,approved_row_id TEXT NOT NULL,candidate_id TEXT NOT NULL,source_page INTEGER NOT NULL,source_row TEXT NOT NULL,symbol_cell_bbox TEXT NOT NULL,geometry TEXT NOT NULL,geometry_signature TEXT NOT NULL,confidence INTEGER NOT NULL,review_actor_id TEXT NOT NULL,review_reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(approved_geometry_version_id) REFERENCES drawing_legend_geometry_approved_versions(id));
CREATE UNIQUE INDEX IF NOT EXISTS drawing_legend_geometry_approved_link_idx ON drawing_legend_geometry_approved_links(approved_geometry_version_id,approved_row_id,candidate_id);
